import datetime,html,json
from pathlib import Path
import studio_order
import runtime as rt
def e(s):return html.escape(str(s),quote=True)
def icon(name):
 paths={'search':'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>','list':'<path d="m3 6 2 2 3-4M11 6h10M3 13l2 2 3-4M11 13h10M3 20l2 2 3-4M11 20h10"/>','settings':'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3" fill="currentColor"/><circle cx="16" cy="17" r="3" fill="currentColor"/>','voice':'<path d="m11 5-6 4H2v6h3l6 4zM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/>','calendar':'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18M8 15h1m6 0h1"/>','user':'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>'}
 return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[name]+'</svg>'
def time_label(value):
 try:return datetime.datetime.fromisoformat(value).strftime('%d.%m · %H:%M')
 except (TypeError,ValueError):return 'ещё не обновлялся'
def render(m,csrf):
 settings=rt.settings();label=settings['owner_label'];login=settings['login']
 token='<input type="hidden" name="csrf" value="'+e(csrf)+'">';prefs=m.load('preferences.json',{});status=m.load('cleanup-status.json',{});auth=m.load('myshows-auth.json',{});entries=m.watching();health=json.loads((rt.feed_state_root()/'status.json').read_text())
 cleanup_on=rt.cleanup_enabled();cleanup_note='' if cleanup_on else '<p class="notice">Автоочистка отключена оператором (cleanup_enable). Включите её в config.json, если нужен автоматический выпуск места.</p>'
 body='<header class="masthead"><div class="brand"><span class="mark">M</span><span>МОЯ МЕДИАТЕКА</span></div><a class="profile" href="#settings">'+icon('user')+e(label)+'</a><form method="post" action="/logout">'+token+'<button class="quiet logout">Выйти</button></form></header><div class="toolbar" id="watching"><div class="heading"><div><h1 id="view-title">Озвучка</h1></div><span class="counter"><span id="visible-count" aria-live="polite">'+str(len(entries))+'</span> <span id="count-unit">сериалов</span></span></div><div class="search">'+icon('search')+'<input type="search" id="series-search" aria-label="Поиск в моих сериалах" placeholder="Найти сериал" autocomplete="off"></div></div><p class="sync-line">MyShows · синхронизация <strong>'+e(time_label(health.get('updated')))+'</strong></p><section id="voice-view" class="series-list" aria-label="Сериалы, которые я смотрю">'
 badge_prefs={}
 for sid,p in prefs.items():
  idx=rt.resolve_studio(m.STUDIOS,p.get('studio'))
  if idx is not None:badge_prefs[str(sid)]=m.STUDIOS[idx]['name']
 badge_config={'studios':studio_order.effective(m.STUDIOS),'preferred':badge_prefs}
 body+='<div id="media-badge-config" hidden data-config="'+e(json.dumps(badge_config,ensure_ascii=False))+'"></div>'
 for index,entry in enumerate(entries):
  sr=entry['series'];sid=sr['id'];p=prefs.get(str(sid),{});choice=p.get('studio');idx=rt.resolve_studio(m.STUDIOS,choice);voice=m.STUDIOS[idx]['name'] if idx is not None else 'Общий приоритет озвучек';options='<option value="-1">По умолчанию</option>'
  for i in studio_order.indices(m.STUDIOS):
   x=m.STUDIOS[i];options+=f'<option value="{i}"'+(' selected' if idx==i else '')+'>'+e(x['name'])+'</option>'
  modes=''.join('<option value="'+v+'"'+(' selected' if p.get('mode','fallback')==v else '')+'>'+n+'</option>' for v,n in [('fallback','С запасными озвучками'),('strict','Только выбранная озвучка')]);strict=choice is not None and p.get('mode')=='strict';mode='<span class="mode'+('' if strict else ' soft')+'">'+('ТОЛЬКО ЭТА' if strict else 'С ЗАПАСНЫМИ')+'</span>' if choice is not None else '';live=sr.get('status') in ('continuing','upcoming');year=sr.get('year') or '';search=(entry['title']+' '+sr['title']).casefold()
  image_loading='fetchpriority="high"' if index==0 else 'loading="lazy"'
  body+=f'<details class="show" id="show-{sid}" data-search="{e(search)}"><summary><img class="cover" src="/cover/{sid}.jpg" alt="" width="156" height="91" {image_loading} decoding="async"><div class="show-copy"><strong class="show-title">{e(entry["title"])}</strong><div class="show-meta">{e(year)} · {e(sr["title"])}</div><div class="show-voice">'+icon('voice')+e(voice)+mode+'</div></div><div class="show-end"><span class="air'+(' live' if live else '')+'">'+('ON AIR' if live else 'ENDED')+'</span><span class="chevron" aria-hidden="true"></span></div></summary><div class="editor"><form class="preference-form" method="post" action="/preference">'+token+f'<input type="hidden" name="series" value="{sid}"><label>Предпочитаемая озвучка<select name="studio">{options}</select></label><label>Если озвучка ещё не вышла<select name="mode">{modes}</select></label><button>Сохранить</button></form><p class="hint">Только эта озвучка — ждём выбранную студию. С запасными — разрешаем другие по общему приоритету. Качество сравнивается первым.</p></div></details>'
 body+='</section><p id="empty-search" class="empty" hidden>Ничего не найдено. Попробуйте другое название.</p>'+(rt.ui_dir()/'dialog.html').read_text()
 appearance='<div class="panel" id="appearance-panel"><h3>Внешний вид</h3><button id="show-search" class="preference-switch quiet" type="button" role="switch" aria-checked="true" aria-label="Показывать строку поиска"><span>Показывать строку поиска</span><span class="switch-track" aria-hidden="true"></span></button><p>Скрывайте поиск, чтобы оставить больше места для карточек сериалов. Настройка сохраняется на этом устройстве.</p><button id="media-details-switch" class="preference-switch quiet" type="button" role="switch" aria-checked="true" aria-label="Показывать качество и озвучку"><span>Показывать качество и озвучку</span><span class="switch-track" aria-hidden="true"></span></button><p>Качество файла и аудиодорожки читаются из фактических медиафайлов. Выключите, чтобы вернуть компактный вид серий; настройка действует только на этом устройстве.</p></div>'
 player='<div class="panel" id="player-panel"><h3>Клиент воспроизведения</h3><label class="playback-row">Плеер для переходов «В медиатеке»<select id="playback-client" aria-label="Клиент воспроизведения"><option value="auto">Автоматически</option></select></label><p id="playback-help" class="hint">Выбор сохраняется только на этом устройстве. Подключите тот же сервер и аккаунт в выбранном клиенте.</p></div>'
 events='<div class="panel" id="events-panel"><div class="status-row"><span class="status-title">События и уведомления</span><button type="button" id="events-journal-toggle" class="quiet" aria-expanded="false" aria-controls="events-journal">Журнал</button></div><p>События загрузок и новых серий ведутся на сервере и настраиваются для всего аккаунта. Разрешение показывать уведомления — отдельно для каждого устройства.</p><button id="events-account-enabled" class="preference-switch quiet" type="button" role="switch" aria-checked="false" aria-label="События аккаунта включены" disabled><span>События аккаунта (все устройства)</span><span class="switch-track" aria-hidden="true"></span></button><div class="events-types" id="events-types" aria-label="Типы событий аккаунта"><button type="button" class="preference-switch quiet" role="switch" aria-checked="false" aria-label="Событие: начало загрузки" data-event-type="download_started" disabled><span>Начало загрузки</span><span class="switch-track" aria-hidden="true"></span></button><button type="button" class="preference-switch quiet" role="switch" aria-checked="false" aria-label="Событие: раздача скачана" data-event-type="torrent_complete" disabled><span>Раздача скачана</span><span class="switch-track" aria-hidden="true"></span></button><button type="button" class="preference-switch quiet" role="switch" aria-checked="false" aria-label="Событие: появилось в медиатеке" data-event-type="library_ready" disabled><span>Появилось в медиатеке</span><span class="switch-track" aria-hidden="true"></span></button><button type="button" class="preference-switch quiet" role="switch" aria-checked="false" aria-label="Событие: новая серия" data-event-type="new_episode" disabled><span>Новая серия</span><span class="switch-track" aria-hidden="true"></span></button><button type="button" class="preference-switch quiet" role="switch" aria-checked="false" aria-label="Событие: проверка замены запущена" data-event-type="upgrade_started" disabled><span>Ежедневная проверка замены</span><span class="switch-track" aria-hidden="true"></span></button><button type="button" class="preference-switch quiet" role="switch" aria-checked="false" aria-label="Событие: результат замены" data-event-type="upgrade_result" disabled><span>Результат замены</span><span class="switch-track" aria-hidden="true"></span></button><button id="events-show-titles" class="preference-switch quiet" type="button" role="switch" aria-checked="false" aria-label="Показывать названия в уведомлениях" disabled><span>Показывать названия сериалов</span><span class="switch-track" aria-hidden="true"></span></button></div><p class="hint">Переключатели выше меняют настройки аккаунта: они действуют на всех устройствах. Без названий уведомления показывают общие формулировки — приватно на экране блокировки.</p><h4>Это устройство</h4><p id="events-device-note" class="hint">Браузер может показывать события, пока панель открыта. Приложение Dubs показывает их в фоне, без открытой страницы.</p><button id="events-device-enabled" class="preference-switch quiet" type="button" role="switch" aria-checked="false" aria-label="Уведомления на этом устройстве включены"><span>Уведомления на этом устройстве</span><span class="switch-track" aria-hidden="true"></span></button><button id="events-notify-request" class="quiet" type="button" hidden>Разрешить уведомления в браузере</button><p id="events-status" class="hint" role="status"></p><div id="events-journal" hidden><h4>Журнал событий</h4><ol id="events-journal-list" class="journal-list"></ol><p id="events-journal-empty" class="hint" hidden>Событий пока нет.</p><button id="events-journal-older" class="quiet" type="button" hidden>Показать ещё</button></div></div>'
 head='<div class="settings-head"><span class="connected">'+('MyShows подключён' if auth.get('token') else 'Нужен вход MyShows')+'</span></div>'
 cleanup='<div class="panel" id="cleanup-panel"><div class="status-row"><span class="status-title">Просмотрено — освободить место</span><span class="pill">'+('КАЖДЫЕ 30 МИН' if cleanup_on else 'ОТКЛЮЧЕНО')+'</span></div><p>'+('Просмотренные в MyShows серии автоматически удаляются из медиатеки и проверенных исходных загрузок. Мониторинг отключается, чтобы они не скачались снова.' if cleanup_on else 'Автоочистка выключена: подключение MyShows само по себе ничего не удаляет. Удаление просмотренного включается только настройкой cleanup_enable в конфигурации.')+'</p>'+cleanup_note+'<p>'+e(status.get('state','Ещё не проверялось'))+'</p>'
 if status.get('time'):cleanup+='<p><small>Последняя проверка · '+e(datetime.datetime.fromtimestamp(status['time']).astimezone().strftime('%d.%m · %H:%M'))+'</small></p>'
 if status.get('errors'):cleanup+='<p class="notice">Не обработано сериалов: '+str(len(status['errors']))+'</p>'
 cleanup+='<form method="post" action="/check">'+token+'<button class="quiet">Проверить сейчас</button></form><details><summary>История удалений</summary><pre>'+e(json.dumps(m.load('deleted.json',[])[-20:],ensure_ascii=False,indent=2))+'</pre></details></div>'
 account='<div class="panel" id="account-panel"><h3>Аккаунт MyShows</h3><p>'+e(login or 'аккаунт MyShows')+' · '+('аккаунт подключён' if auth.get('token') else 'подключите аккаунт для удаления просмотренного')+'</p><details'+('' if auth.get('token') else ' open')+'><summary>Подключить или обновить вход</summary><form class="account-form" method="post" action="/myshows-login">'+token+'<label>Логин или e-mail MyShows<input name="username" value="'+e(login)+'" autocomplete="section-myshows username" required></label><label>Пароль MyShows<input name="password" type="password" autocomplete="section-myshows current-password" required></label><button>Подключить MyShows</button></form><p>Пароль не сохраняется. После истечения токена потребуется повторный вход.</p></details><details><summary>Подключить токеном</summary><form class="token-form" method="post" action="/myshows">'+token+'<label>Токен доступа MyShows<input type="password" name="token" autocomplete="off" required></label><button>Подключить</button></form><p>Токен должен принадлежать '+e(login or 'владельцу')+'. Подключение синхронизирует отметки «просмотрено»; удаление файлов включается только настройкой cleanup_enable.</p></details></div>'
 download='<div class="panel" id="download-panel"><details><summary>Как выбирается загрузка</summary><p>Новые релизы проверяются каждые 15 минут. Русский язык обязателен. Личная озвучка имеет приоритет при одинаковом качестве. В режиме с запасными другая студия может скачаться раньше выбранной. Настройки применяются к будущим загрузкам. Уже скачанные файлы сохраняются, но ежедневно в '+e(str(settings.get('daily_upgrade_hour',18)))+':00 проверяются: более высокое качество или выбранная озвучка заменяют текущую версию, если новая раздача лучше.</p></details></div>'
 artifacts=m.mobile_artifacts() if hasattr(m,'mobile_artifacts') else []
 apps=''
 if artifacts:
  apps+='<div class="panel" id="apps-panel"><h3>Приложения Dubs</h3>'
  for a in artifacts:apps+='<p><a href="/apps/'+e(a['file'])+'">'+e(a['label'])+'</a></p>'
  server=rt.settings()['jellyfin_url']
  if server:apps+='<p>Для перехода «В медиатеке» настройте Swiftfin на iOS или Findroid на Android. Сервер: '+e(server)+'.</p>'
  apps+='</div>'
 order=studio_order.view(m.STUDIOS)
 editor='<form id="studio-order-form" method="post" action="/api/studio-order"><h3>Общий приоритет озвучек</h3><p>Для всех сериалов по умолчанию. Выше — предпочтительнее. Личный выбор сериала сохраняет приоритет. Переставьте строки или используйте кнопки.</p>'+token+'<ol id="studio-order-list" aria-label="Приоритет студий">'
 for name in order['order']:
  editor+='<li draggable="true" data-studio="'+e(name)+'"><span>'+e(name)+'</span><button type="button" class="quiet" data-move="-1" aria-label="Вверх: '+e(name)+'">↑</button><button type="button" class="quiet" data-move="1" aria-label="Вниз: '+e(name)+'">↓</button></li>'
 editor+='</ol><button type="submit" id="studio-order-save" class="quiet">Сохранить порядок</button><p id="studio-order-status" role="status" aria-live="polite" data-state="'+e(order['state'])+'">'+e(order['message'])+'</p></form>'
 editor='<div class="panel" id="studio-order-panel">'+editor+'</div>'
 body+='<section class="settings" id="settings">'+head+'<div class="settings-column settings-large">'+editor+events+account+apps+'</div><div class="settings-column settings-short">'+appearance+player+cleanup+download+'</div>'
 body+='</section><p class="footer-note">MYSHOWS × SONARR · ВАША МЕДИАТЕКА, ВАШИ ПРАВИЛА</p><nav class="bottom-nav" aria-label="Навигация"><a class="active" data-tab="voice" href="#voice">'+icon('voice')+'<span>Озвучка</span></a><a data-tab="released" href="#released">'+icon('list')+'<span>Вышло</span></a><a data-tab="upcoming" href="#upcoming">'+icon('calendar')+'<span>Будет</span></a><a data-tab="settings" href="#settings">'+icon('settings')+'<span>Настройки</span></a></nav>';return body
